#include <stdio.h>
#include <stddef.h>

int main(void) {
    size_t count = 3;
    long long big = 3000000000LL; /* LL suffix: long long. */
    double avg = 8.0 / 3;        /* double division. */
    char grade = 'B';

    printf("%zu items\n", count);     /* size_t. */
    printf("%lld\n", big);            /* long long. */
    printf("%.2f\n", avg);            /* double: 2.67. */
    printf("%c\n", grade);            /* char (promoted to int). */

    double price;
    if (scanf("%lf", &price) == 1)    /* scanf: %lf and an address. */
        printf("%.2f\n", price);
    return 0;
}
```

| Type | printf | scanf |
|---|---|---|
| int. | `%d`. | `%d` + `&x`. |
| long. | `%ld`. | `%ld`. |
| size_t. | `%zu`. | `%zu`. |
| double. | `%f`. | `%lf`. |
| char. | `%c`. | `%c` (use " %c" to skip spaces). |

